                     Id = rowId,
                     WorkItemId = itemId,
                     Phase = phase,
                     Iteration = iteration,
                     Step = $"agent.tool_call.{safeToolName}",
                     StartedAt = startedAt,
                     MetadataJson = metaJson,
                 }, CancellationToken.None);
                 await _timings.EndAsync(rowId, startedAt, 0, CancellationToken.None);
